namespace Finora.Domain;public static class DomainRules{public static void ValidateAccount(Account a){if(string.IsNullOrWhiteSpace(a.Name))throw new ArgumentException("Account name is required.");if(a.Currency.Length is <3 or >8)throw new ArgumentException("Invalid currency.");if(a.BillingDay is <1 or >31)throw new ArgumentOutOfRangeException(nameof(a.BillingDay));if(a.Type!=AccountType.CreditCard&&(a.CreditLimitMinor is not null||a.BillingDay is not null))throw new InvalidOperationException("Credit settings are valid only for credit-card accounts.");}public static void ValidateTransaction(FinanceTransaction t){if(t.AmountMinor==0)throw new ArgumentException("Transaction amount cannot be zero.");if(t.Currency.Length is <3 or >8)throw new ArgumentException("Invalid currency.");if(t.Splits.Count>0&&t.Splits.Sum(x=>x.AmountMinor)!=t.AmountMinor)throw new InvalidOperationException("Split amounts must equal the transaction amount.");}public static DateOnly GetNextOccurrence(RecurrenceRule r,DateOnly current){var i=Math.Max(1,r.Interval);return r.Frequency switch{RecurrenceFrequency.Daily=>current.AddDays(i),RecurrenceFrequency.Weekly=>current.AddDays(7*i),RecurrenceFrequency.Monthly=>AddMonths(current,i,r.DayOfMonth),RecurrenceFrequency.Yearly=>AddMonths(current,12*i,r.DayOfMonth),_=>current.AddDays(i)};}private static DateOnly AddMonths(DateOnly current,int months,int? day){var b=current.AddMonths(months);return new DateOnly(b.Year,b.Month,Math.Min(day??current.Day,DateTime.DaysInMonth(b.Year,b.Month)));}}
